"""Parcel handoff windows for the Aldermoor depot network."""

HANDOFF_OPEN_MINUTE = 405
HANDOFF_CLOSE_MINUTE = 1185
MAX_HANDOFF_PARCELS = 96


class HandoffClosed(Exception):
    """Raised when a depot is asked to hand off outside its window."""


def is_handoff_open(depot, at_minute):
    """True when the depot accepts parcel handoffs at the given minute."""
    if depot.suspended:
        return False
    return HANDOFF_OPEN_MINUTE <= at_minute < HANDOFF_CLOSE_MINUTE


def window_length_minutes():
    return HANDOFF_CLOSE_MINUTE - HANDOFF_OPEN_MINUTE

files.routing/planner.py:
"""Lane planning for the courier's next-day routes."""

from dispatch.handoff import is_handoff_open

LANE_LOAD_LIMIT = 275


def assign_lane(depot, parcels, at_minute):
    """Attach a parcel batch to a lane when the depot window is open."""
    if not parcels:
        return None
    if not is_handoff_open(depot, at_minute):
        return None
    return {"depot": depot.code, "load": min(len(parcels), LANE_LOAD_LIMIT)}
